        FeeParamsForRead calldata _params,
        IDVN.DstConfig calldata _dstConfig,
        bytes calldata _cmd,
        bytes calldata _options
    ) external view returns (uint256 fee);

    function version() external view returns (uint64 major, uint8 minor);
}

